// src/pages/AboutPage.js
import { useState } from 'react';
import { Link } from 'react-router-dom';
import mePhoto from '../assets/me.jpg';

function AboutPage() {
  const [darkMode, setDarkMode] = useState(false);
  const toggleTheme = () => setDarkMode(prev => !prev);

  return (
    <div className={darkMode ? 'dark-mode' : ''}>
      <header className="header">
        <h1>My Personal Interest</h1>
        <nav>
          <ul className="navList">
            <li><Link to="/">Home</Link></li>
            <li><Link to="/about" className="active">About</Link></li>
            <li><Link to="/contact">Contact</Link></li>
            <li><Link to="/register">Register</Link></li>
            <li><Link to="/game">Game</Link></li>
          </ul>
        </nav>
      </header>

      <button className="theme-toggle" onClick={toggleTheme}>Toggle Dark/Light</button>

      <section>
        <h2>My Story Through Dance</h2>
        <img src={mePhoto} alt="Photo of Donato" />
        <p>My name is <strong>Donato G. Ureta Jr.</strong>, also known as <strong>DJ</strong>. I am from San Eugenio, Aringay, La Union. This webpage shares my personal journey in discovering my passion for dance.</p>
      </section>

      <footer className="footer">
        <p>Contact: dxxxxxxxxxxx@gmail.com | Phone: 09xxxxxxx8</p>
        <p>&copy; 2026 My Dance Journey. All rights reserved.</p>
      </footer>
    </div>
  );
}

export default AboutPage;
